'use strict';
// Actual WGSL gate for controlled prepared graph arithmetic/bookkeeping only.
// No native capture or rigid-body trajectory is generated by this test.
const{test}=require('node:test'),assert=require('node:assert/strict'),{pathToFileURL}=require('node:url');
const J=require('../src/experimental-contact-graph-journal'),{seed,at,copy,same}=require('./contact-graph-bounded-fixture.cjs');
async function trace(j,s){
 const token={},trace=[];j.claim(token);let projection=j.createProjection(token);
 const frames=[{3:.25},{2:.4,3:.25},{0:-10,2:.4,3:.25},{2:.4,3:.25},{3:1150},{}];
 try{for(let i=0;i<frames.length;i++){
  const p=at(s,frames[i]),r=await j.prepare(p,token),transitions=i===0?[{collider1:r.graph.edges[0].collider1,collider2:r.graph.edges[0].collider2,active:true}]:[];
  j.narrowTransitions(transitions,token);await j.postSolve(p,token);projection=J.projectReceipts([r.receipt],projection,j.backend).projection;const v=J.viewReceipt(r.receipt);delete v.backend;trace.push(v);j.commit(token);assert.deepEqual(J.projectionSnapshot(projection),j.snapshot());
 }
 const before=j.snapshot();await assert.rejects(()=>j.prepare(at(s,{1:0,2:0,3:0}),token),/Unsupported simultaneous fresh-pair/);assert.deepEqual(j.snapshot(),before);
 const p=at(s,{3:.25}),r=await j.prepare(p,token);j.narrowTransitions([],token);const unchanged=J.viewReceipt(r.receipt).after,bad=copy(p);bad[3].translation[0]=Infinity;await assert.rejects(()=>j.postSolve(bad,token),/Exact finite native f32 vector/);assert.deepEqual(J.viewReceipt(r.receipt).after,unchanged);await j.postSolve(p,token);const aborted=J.projectReceipts([r.receipt],projection,j.backend).projection;j.abort(token);assert.deepEqual(j.snapshot(),before);assert.throws(()=>J.projectionSnapshot(aborted),/origin-bound/);
 assert.ok(trace.some(r=>r.operations.some(x=>x.kind==='edge-relocated')));assert.ok(trace.some(r=>r.contactEvents.some(x=>x.started===false)));assert.ok(trace.some(r=>r.after.edges.some(e=>same(e.collider2,s.bodies[3].primary))));return trace;
 }finally{j.abort(token);j.release(token);j.dispose();}
}
test('actual WGSL N=4 prepared graph matches the common CPU arithmetic and graph transactions',{timeout:60000,skip:!process.env.GPU_NATIVE_MODULE&&process.env.REQUIRE_WEBGPU!=='1'},async t=>{
 assert.ok(process.env.GPU_NATIVE_MODULE,'GPU_NATIVE_MODULE is required for the actual WGSL gate');const s=seed(),reference=await trace(J.createReferenceStage(s),s),{create,globals}=await import(pathToFileURL(process.env.GPU_NATIVE_MODULE).href);Object.assign(globalThis,globals);const gpu=create(['backend=vulkan']),adapter=await gpu.requestAdapter();assert.ok(adapter,'Native Vulkan adapter required');const device=await adapter.requestDevice();
 try{const actual=await trace(await J.createGpuStage(device,s),s);assert.deepEqual(actual,reference);t.diagnostic(JSON.stringify({backend:'actual-webgpu',bodyCount:4,preparedColliderCount:24,frames:actual.length,inputFloats:J.arithmeticLayout(4).inputFloats,scope:'Synthetic prepared graph arithmetic and transaction equality only; not native Rapier parity or four-ball world admission'}));}finally{device.destroy();}
});
